style.svg:
 is exactly the window; the app scrolls inside .scroll, so the fixed
   layers (cover page, player, cursor light) stay glued to the window. */

:root { overflow: hidden; }
body { height: 100%; overflow: hidden; }
.scroll {
  height: 100%;
  overflow-y: auto;
  overflow-x: hidden;
  scrollbar-gutter: stable;
  scrollbar-color: #8a5a14 #0a0a0a;
}
svg.gated .scroll,
svg.playing .scroll { overflow: hidden; }

body.script:
//
    // Every visit starts on the cover page below. When pyrite is itself embedded (the about:blank
    // shield) there is nothing to hide from, so skip straight to the projects.
    var svgRoot = document.documentElement.localName === "svg"
      ? document.documentElement
      : document.querySelector("svg:has(foreignObject)");
    try { if (window.top !== window.self) svgRoot.classList.remove("gated"); }
    catch (e) { svgRoot.classList.remove("gated"); }
//
